const input = $input.first().json || {};

const LIVE_SEND_ENABLED = false; // HARD KILL SWITCH FOR V1.

const operation = String(input.operation || '').trim();

if (!['validate_payload', 'send_email'].includes(operation)) {
  throw new Error(`SMTP2GO broker rejected operation: ${operation}`);
}

const sender = String(input.sender || '').trim();
const subject = String(input.subject || '').trim();
const textBody = String(input.text_body || '').trim();
const taskKey = String(input.task_key || '').trim();
const contentHash = String(input.content_hash || '').trim();

let to = input.to;
if (typeof to === 'string') to = [to];
if (!Array.isArray(to)) to = [];

to = to.map(v => String(v || '').trim()).filter(Boolean);

const problems = [];

if (!sender) problems.push('SENDER_REQUIRED');
if (!subject) problems.push('SUBJECT_REQUIRED');
if (!textBody) problems.push('TEXT_BODY_REQUIRED');
if (!taskKey) problems.push('TASK_KEY_REQUIRED');
if (!contentHash) problems.push('CONTENT_HASH_REQUIRED');
if (to.length !== 1) problems.push('EXACTLY_ONE_RECIPIENT_REQUIRED');
if (to.some(v => !v.includes('@'))) problems.push('INVALID_RECIPIENT');

if (problems.length) {
  throw new Error(`SMTP2GO payload rejected: ${problems.join(',')}`);
}

const payload = {
  sender,
  to,
  subject,
  text_body: textBody,
  fastaccept: true,
  custom_headers: [
    {
      header: 'X-Saray-GTM-Task-Key',
      value: taskKey
    },
    {
      header: 'X-Saray-GTM-Content-Hash',
      value: contentHash
    }
  ]
};

if (operation === 'send_email' && !LIVE_SEND_ENABLED) {
  throw new Error(
    'SMTP2GO_LIVE_SEND_DISABLED: broker V1 is intentionally hard-disabled for live sending.'
  );
}

return [{
  json: {
    broker: 'smtp2go',
    broker_version: 'SMTP2GO-BROKER-V1.0.0',
    operation,
    live_send_enabled: LIVE_SEND_ENABLED,
    endpoint: 'https://api.smtp2go.com/v3/email/send',
    payload
  }
}];

const req = $('Validate Envelope and Kill Switch').first().json;
const raw = $input.first().json || {};

const data = raw.data || {};
const failed = Number(data.failed ?? 0);
const succeeded = Number(data.succeeded ?? 0);
const failures = Array.isArray(data.failures) ? data.failures : [];
const emailId = data.email_id ? String(data.email_id) : null;

const providerSucceeded =
  succeeded >= 1 &&
  failed === 0 &&
  failures.length === 0 &&
  Boolean(emailId);

return [{
  json: {
    broker: 'smtp2go',
    broker_version: req.broker_version,
    operation: req.operation,
    provider_succeeded: providerSucceeded,
    provider_message_id: emailId,
    succeeded,
    failed,
    failures,
    raw_response: raw
  }
}];

const req = $('Validate Envelope and Kill Switch').first().json;

return [{
  json: {
    broker: 'smtp2go',
    broker_version: req.broker_version,
    operation: 'validate_payload',
    live_send_enabled: false,
    payload_valid: true,
    endpoint: req.endpoint,
    provider_payload: req.payload
  }
}];
